        'edition_en_cours' => ['text' => 'Édition en cours.', 'context' => 'JavaScript interface text in omo/document_share.js'],
        'lecture_partagee_du_document' => ['text' => 'Lecture partagée du document.', 'context' => 'JavaScript interface text in omo/document_share.js'],
        'share_delete_confirm' => ['text' => 'Supprimer le lien « {label} » ?', 'context' => 'Translated interface feedback with named interpolation variables.'],
        'vote_multiple_summary' => ['text' => 'Plusieurs réponses (max. {count})', 'context' => 'Translated interface feedback with named interpolation variables.'],
        'invitation_member_count' => ['one' => '{count} membre', 'other' => '{count} membres', 'context' => 'Translated interface feedback with named interpolation variables.'],
        'invitation_guest_count' => ['one' => '{count} invité', 'other' => '{count} invités', 'context' => 'Translated interface feedback with named interpolation variables.'],
        'editing_by_name' => ['text' => 'Édition en cours par {name}.', 'context' => 'Translated interface feedback with named interpolation variables.'],
        'displayed_text_placeholder' => ['text' => 'Texte affiché', 'context' => 'Translated interface feedback with named interpolation variables.'],
    ];
    return $sourceLang;
}

function omoUiJsPayload(): array
{
    static $payloads = [];
    $locale = translationBundleResolveRequestLocale('lang', translationBundleGetSupportedLocales(), 'fr');
    if (isset($payloads[$locale])) return $payloads[$locale];
    $sourceLang = omoUiJsSourceLang();
    $bundle = loadTranslationBundle('omo_shared_javascript', $locale, $sourceLang);
    $payload = [];
    foreach ($sourceLang as $key => $entry) {
        $activeEntry = translationBundleResolveEntry($key, $bundle, $sourceLang);
        if (isset($entry['one'], $entry['other'])) {
            $payload[$key] = [];
            foreach (['one', 'other'] as $form) {
                $payload[$key][$form] = t($key, [], [$key => ['text' => $activeEntry[$form] ?? $entry[$form]]], $sourceLang);
            }
        } else {
            $payload[$key] = t($key, [], $bundle, $sourceLang);
        }
    }
    return $payloads[$locale] = $payload;
}
